'use server'

import { revalidatePath } from 'next/cache'
import fs from 'node:fs/promises'
import path from 'node:path'

const dataPath = path.join(process.cwd(), 'app', 'data.json')

export async function toggleNotifications() {
  const data = JSON.parse(await fs.readFile(dataPath, 'utf-8'))
  data.notifications = !data.notifications
  await fs.writeFile(dataPath, JSON.stringify(data, null, 2))
  revalidatePath('/')
}

import fs from 'node:fs/promises'
import path from 'node:path'

const dataPath = path.join(process.cwd(), 'app', 'data.json')

export async function getNotifications() {
  try {
    const content = await fs.readFile(dataPath, 'utf-8')
    return JSON.parse(content).notifications
  } catch (error) {
    // If file doesn't exist or is invalid, return default
    return false
  }
}

export async function setNotifications(value: boolean) {
  const data = { notifications: value }
  await fs.writeFile(dataPath, JSON.stringify(data, null, 2))
}

'use server'

import { revalidatePath } from 'next/cache'
import { getNotifications, setNotifications } from './lib/db'

export async function toggleNotifications() {
  const current = await getNotifications()
  await setNotifications(!current)
  revalidatePath('/')
}

import { getNotifications } from './lib/db'
import { toggleNotifications } from './actions'

export default async function Home() {
  const notificationsEnabled = await getNotifications()

  return (
    <main>
      <h1>Settings</h1>
      <p>Current preference: {notificationsEnabled ? 'ON' : 'OFF'}</p>

      <form action={toggleNotifications}>
        <button type="submit">
          Toggle Notifications
        </button>
      </form>
    </main>
  );
}

